import { test, expect } from '@playwright/test';

test.describe('Search Tolerance for Minor Spelling Mistakes', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should return correct results when search query contains minor spelling mistakes', async ({ page }) => {
    // Verify search input is visible
    const searchInput = page.getByPlaceholder('Search products...');
    await expect(searchInput).toBeVisible();

    // Enter misspelled search query
    await searchInput.fill('apple pie');

    // Click search button
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for results to load
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify results container is visible
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();

    // Verify results list contains expected items
    const resultItems = page.getByTestId('result-item');
    const count = await resultItems.count();
    expect(count).toBeGreaterThan(0);

    // Verify at least one result contains the correct spelling
    const firstResult = page.getByTestId('result-item').first();
    const resultText = await firstResult.textContent();
    expect(resultText).toContain('apple');
    expect(resultText).toContain('pie');

    // Verify search term is displayed in results
    const searchTermDisplay = page.getByText('apple pie');
    await expect(searchTermDisplay).toBeVisible();
  });

  test('should handle multiple minor spelling errors and return relevant results', async ({ page }) => {
    // Enter query with multiple errors
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('televison');

    // Click search button
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for results to load
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify results container is visible
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();

    // Verify results list contains expected items
    const resultItems = page.getByTestId('result-item');
    const count = await resultItems.count();
    expect(count).toBeGreaterThan(0);

    // Verify at least one result contains the correct spelling
    const firstResult = page.getByTestId('result-item').first();
    const resultText = await firstResult.textContent();
    expect(resultText).toContain('television');

    // Verify search term is displayed with correction suggestion
    const searchTermDisplay = page.getByText('televison');
    await expect(searchTermDisplay).toBeVisible();

    // Verify correction suggestion is available
    const correctionSuggestion = page.getByRole('link', { name: /television/i });
    await expect(correctionSuggestion).toBeVisible();

    // Click correction suggestion
    await correctionSuggestion.click();

    // Verify search is updated with corrected term
    await expect(searchInput).toHaveValue('television');

    // Verify results are updated after correction
    await page.waitForTimeout(500);
    const updatedResultItems = page.getByTestId('result-item');
    const updatedCount = await updatedResultItems.count();
    expect(updatedCount).toBeGreaterThan(0);
  });
});
